#include "gc9b72_spi.h"
#include "hella_reader.hpp"
#include "lvgl.h"
#include "esp_timer.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include <algorithm>
#include <cstdio>
namespace {lv_obj_t *screen,*oil,*bar,*battery,*peak,*state;float maxOil=-40,maxBar=0;lv_color_t mint=lv_color_hex(0x20e889),cyan=lv_color_hex(0x28c5ee),muted=lv_color_hex(0x939aa4);lv_obj_t* label(const char*s,int size,lv_color_t color,int y){auto*l=lv_label_create(screen);lv_label_set_text(l,s);lv_obj_set_style_text_color(l,color,0);lv_obj_set_style_text_font(l,size>=40?&lv_font_montserrat_40:size>=32?&lv_font_montserrat_32:size>=24?&lv_font_montserrat_24:size>=18?&lv_font_montserrat_18:&lv_font_montserrat_14,0);lv_obj_set_width(l,320);lv_obj_set_style_text_align(l,LV_TEXT_ALIGN_CENTER,0);lv_obj_align(l,LV_ALIGN_CENTER,0,y);return l;}void task(void*){int64_t last=esp_timer_get_time();char b[48];for(;;){int64_t now=esp_timer_get_time();lv_tick_inc((now-last)/1000);last=now;auto r=hella::read();if(r.oil_valid){maxOil=std::max(maxOil,r.oil_c);std::snprintf(b,sizeof(b),"%.0f",r.oil_c);lv_label_set_text(oil,b);}if(r.pressure_valid){maxBar=std::max(maxBar,r.pressure_bar);std::snprintf(b,sizeof(b),"%.1f bar",r.pressure_bar);lv_label_set_text(bar,b);std::snprintf(b,sizeof(b),"PICO  %.1f bar",maxBar);lv_label_set_text(peak,b);}std::snprintf(b,sizeof(b),"%.1f V",r.battery_v);lv_label_set_text(battery,b);lv_label_set_text(state,(r.oil_valid||r.pressure_valid)?"LECTURA HELLA ACTIVA":"ESPERANDO SENSOR");lv_timer_handler();vTaskDelay(pdMS_TO_TICKS(50));}}}
extern "C" void app_main(){lv_init();if(!gc9b72_spi::init()||!hella::begin())return;screen=lv_obj_create(nullptr);lv_obj_remove_style_all(screen);lv_obj_set_size(screen,466,466);lv_obj_set_style_bg_color(screen,lv_color_hex(0x03060a),0);lv_obj_set_style_bg_opa(screen,LV_OPA_COVER,0);lv_obj_clear_flag(screen,LV_OBJ_FLAG_SCROLLABLE);auto*outer=lv_obj_create(screen);lv_obj_remove_style_all(outer);lv_obj_set_size(outer,438,438);lv_obj_center(outer);lv_obj_set_style_radius(outer,LV_RADIUS_CIRCLE,0);lv_obj_set_style_bg_opa(outer,LV_OPA_TRANSP,0);lv_obj_set_style_border_width(outer,3,0);lv_obj_set_style_border_color(outer,lv_color_hex(0x263039),0);auto*arc=lv_arc_create(screen);lv_obj_set_size(arc,406,406);lv_obj_center(arc);lv_arc_set_rotation(arc,135);lv_arc_set_bg_angles(arc,0,270);lv_arc_set_range(arc,0,100);lv_arc_set_value(arc,65);lv_obj_remove_style(arc,nullptr,LV_PART_KNOB);lv_obj_set_style_arc_width(arc,8,LV_PART_MAIN);lv_obj_set_style_arc_color(arc,lv_color_hex(0x20262e),LV_PART_MAIN);lv_obj_set_style_arc_width(arc,8,LV_PART_INDICATOR);lv_obj_set_style_arc_color(arc,mint,LV_PART_INDICATOR);lv_obj_clear_flag(arc,LV_OBJ_FLAG_CLICKABLE);label("●  HELLA  OIL",18,mint,-175);label("TEMPERATURA ACEITE",14,muted,-114);oil=label("--",56,lv_color_white(),-55);label("°C",18,muted,0);bar=label("--.- bar",28,lv_color_white(),48);label("PRESION DE ACEITE",14,muted,82);peak=label("PICO  --.- bar",16,mint,124);battery=label("--.- V",20,lv_color_white(),163);state=label("ESPERANDO SENSOR",14,muted,194);lv_screen_load(screen);xTaskCreate(task,"ui",6144,nullptr,5,nullptr);}
